interface SnapshotV2 {
  schema: 2;
  nextSeq: number;
  lastAppliedSeq: number;
  profiles: AttackerProfile[];
}

export class ProfileStore {
  private nextSeqCounter: number = 0;
  private lastAppliedSeqCounter: number = 0;

  load(snapshotPath: string, logPath: string): AttackerProfile[] {
    let profiles: AttackerProfile[] = [];
    if (existsSync(snapshotPath)) {
      const raw = readFileSync(snapshotPath, 'utf8');
      let parsed: { schema?: number; nextSeq?: number; lastAppliedSeq?: number; profiles?: AttackerProfile[] };
      try {
        parsed = JSON.parse(raw);
        if (parsed.schema === 2) {
          this.nextSeqCounter = parsed.nextSeq ?? 0;
          this.lastAppliedSeqCounter = parsed.lastAppliedSeq ?? 0;
          profiles = parsed.profiles ?? [];
        } else {
          profiles = (parsed as any).profiles || [];
        }
      } catch { /* ignore */ }
    }
    // Replay logic and log handling would follow here
    return profiles;
  }

  // ... rest of implementation
}"}}
</tool_request>

